MENU = {"tea": 15, "samosa": 12, "dosa": 40}

def bill(order):
    return sum(MENU[item] * qty for item, qty in order.items())

def receipt(order):
    lines = [f"{item} x{qty}" for item, qty in order.items()]
    return ", ".join(lines) + f" = Rs {bill(order)}"

order = {"tea": 2, "dosa": 1}
print(bill(order))
print(receipt(order))

