class Student:
    def __init__(self, name, marks=None):
        self.name = name
        self.marks = marks or {}

    def average(self):
        if not self.marks:
            return 0
        return sum(self.marks.values()) / len(self.marks)

    def passed(self):
        return all(m >= 35 for m in self.marks.values())

def load(text):
    students = {}
    for line in text.split("\n"):
        parts = line.strip().split(",")
        if len(parts) != 3:
            continue
        name, subject, mark = parts
        try:
            mark = int(mark)
        except ValueError:
            continue
        students.setdefault(name, Student(name)).marks[subject] = mark
    return students

def report(students):
    out = []
    for name in sorted(students):
        s = students[name]
        result = "PASS" if s.passed() else "FAIL"
        out.append(f"{name}: {round(s.average(), 1)}, {result}")
    return out
